#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#define VL 16
#define MR 8
#define KC 256
#else
#define VL 8
#define MR 6
#define KC 384
#endif
#define NR (2 * VL)
#define MC (MR * 8)
#define NCB (NR * 8 > 128 ? 128 : NR * 8)

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
        __builtin_prefetch(c + i * ldc, 1, 3);
        __builtin_prefetch(c + i * ldc + NR - 1, 1, 3);
    }
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
        __builtin_prefetch(b + 8 * NR, 0, 3);
        __builtin_prefetch(a + 8 * MR, 0, 3);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

static void pack_a_panel(const float *A, int n, int i0, int mr, int p0, int kc, float *ap)
{
    int i;
    for (i = 0; i < mr; i++) {
        const float *src = A + (size_t)(i0 + i) * n + p0;
        for (int k = 0; k < kc; k++)
            ap[k * MR + i] = src[k];
    }
    for (; i < MR; i++)
        for (int k = 0; k < kc; k++)
            ap[k * MR + i] = 0.0f;
}

static void pack_b_panel(const float *B, int n, int p0, int kc, int j0, int nr, float *bp)
{
    if (nr == NR) {
        for (int k = 0; k < kc; k++)
            memcpy(bp + (size_t)k * NR, B + (size_t)(p0 + k) * n + j0, NR * sizeof(float));
