        float *dst = bp + (size_t)k * NR;
        int j;
        for (j = 0; j < nr; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static float *g_ap = NULL, *g_bp = NULL;
static size_t g_asz = 0, g_bsz = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) / 4096 * 4096;
    p = (float *)aligned_alloc(64, need);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    int npanA = (n + MR - 1) / MR;
    int npanB = (n + NR - 1) / NR;
    g_ap = grow(g_ap, &g_asz, (size_t)npanA * MR * KC * sizeof(float));
    g_bp = grow(g_bp, &g_bsz, (size_t)npanB * NR * KC * sizeof(float));
    float *ap = g_ap, *bp = g_bp;

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCB - 1) / NCB;
    int ntask = nib * njb;

#pragma omp parallel
