#ifdef _OPENMP
#include <omp.h>
#endif

#if defined(__AVX512F__)
#define VL 16
#define MR 12
#define MC (MR * 16)
#else
#define VL 8
#define MR 6
#define MC (MR * 24)
#endif
#define NR (2 * VL)
#define KC 256

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
        __builtin_prefetch(c + i * ldc, 1, 3);
        __builtin_prefetch(c + i * ldc + NR - 1, 1, 3);
    }
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

/* Pack mc rows of A (cols p0..p0+kc) into MR-interleaved panels, reading rows contiguously. */
static void pack_a_block(const float *A, int n, int i0, int mc, int p0, int kc, float *ap)
{
    for (int p = 0; p < mc; p += MR) {
        int mr = mc - p < MR ? mc - p : MR;
        int i;
        for (i = 0; i < mr; i++) {
            const float *src = A + (size_t)(i0 + p + i) * n + p0;
            for (int k = 0; k < kc; k++)
                ap[k * MR + i] = src[k];
        }
        for (; i < MR; i++)
            for (int k = 0; k < kc; k++)
                ap[k * MR + i] = 0.0f;
        ap += (size_t)kc * MR;
    }
}

/* Pack B rows p0..p0+kc, cols j0..j1 into NR-wide panels (each kc x NR contiguous). */
static void pack_b_band(const float *B, int n, int p0, int kc, int j0, int j1, float *bp)
{
    int w = j1 - j0;
    int nfull = w / NR;
    int rem = w - nfull * NR;
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(p0 + k) * n + j0;
        float *dst = bp + (size_t)k * NR;
        for (int q = 0; q < nfull; q++)
            memcpy(dst + (size_t)q * kc * NR, src + q * NR, NR * sizeof(float));
        if (rem) {
            float *d = dst + (size_t)nfull * kc * NR;
            const float *s = src + nfull * NR;
            int j;
            for (j = 0; j < rem; j++) d[j] = s[j];
            for (; j < NR; j++) d[j] = 0.0f;
        }
    }
}

static float *g_buf = NULL;
static size_t g_cap = 0;

void matmul(const float *A, const float *B, float *C, int n)
{
    int nt = 1;
#ifdef _OPENMP
    nt = omp_get_max_threads();
#endif
    if (nt < 1) nt = 1;
    int Ur = (n + MR - 1) / MR;
    int Uc = (n + NR - 1) / NR;

    /* Choose a pr x pg thread grid minimizing the largest tile, then perimeter. */
    int pr = 1, pg = nt;
    long best = -1, bestper = 0;
    for (int d = 1; d <= nt; d++) {
        if (nt % d) continue;
        int g = nt / d;
        long rr = (Ur + d - 1) / d, cc = (Uc + g - 1) / g;
        long cost = rr * MR * cc * NR;
        long per = rr * MR + cc * NR;
        if (best < 0 || cost < best || (cost == best && per < bestper)) {
            best = cost; bestper = per; pr = d; pg = g;
        }
    }

    int npc = (n + KC - 1) / KC;
    int kcb = (n + npc - 1) / npc;
    int wmax = (Uc + pg - 1) / pg * NR;
    size_t stride = (size_t)wmax * kcb + (size_t)MC * kcb;
    stride = (stride + 1023) / 1024 * 1024;
    size_t need = stride * nt * sizeof(float);
    if (need > g_cap) {
        free(g_buf);
        need = (need + 4095) / 4096 * 4096;
        g_buf = (float *)aligned_alloc(4096, need);
        g_cap = need;
    }
    float *buf = g_buf;

#pragma omp parallel num_threads(nt)
    {
        int tid = 0, nth = 1;
#ifdef _OPENMP
        tid = omp_get_thread_num();
        nth = omp_get_num_threads();
#endif
        float tile[MR * NR] __attribute__((aligned(64)));
        for (int t = tid; t < nt; t += nth) {
            float *bp = buf + stride * t;
            float *ap = bp + (size_t)wmax * kcb;
            int r = t / pg, g = t % pg;
            int i0 = (int)((long)r * Ur / pr) * MR;
            int i1 = (int)((long)(r + 1) * Ur / pr) * MR;
            if (i1 > n) i1 = n;
            int j0 = (int)((long)g * Uc / pg) * NR;
            int j1 = (int)((long)(g + 1) * Uc / pg) * NR;
            if (j1 > n) j1 = n;
            if (i0 >= i1 || j0 >= j1) continue;
            int npan = (j1 - j0 + NR - 1) / NR;

            for (int pc = 0; pc < n; pc += kcb) {
                int kc = n - pc < kcb ? n - pc : kcb;
                int first = (pc == 0);
                pack_b_band(B, n, pc, kc, j0, j1, bp);
                for (int ic = i0; ic < i1; ic += MC) {
                    int mc = i1 - ic < MC ? i1 - ic : MC;
                    pack_a_block(A, n, ic, mc, pc, kc, ap);
                    for (int q = 0; q < npan; q++) {
                        int j = j0 + q * NR;
                        int nr = j1 - j < NR ? j1 - j : NR;
                        const float *bpan = bp + (size_t)q * kc * NR;
                        for (int i = 0; i < mc; i += MR) {
                            int mr = mc - i < MR ? mc - i : MR;
                            const float *apan = ap + (size_t)(i / MR) * kc * MR;
                            float *cp = C + (size_t)(ic + i) * n + j;
                            if (mr == MR && nr == NR) {
                                kernel(kc, apan, bpan, cp, n, first);
                            } else {
                                kernel(kc, apan, bpan, tile, NR, 1);
                                for (int ii = 0; ii < mr; ii++) {
                                    float *crow = cp + (size_t)ii * n;
                                    const float *trow = tile + ii * NR;
                                    if (first)
                                        for (int jj = 0; jj < nr; jj++) crow[jj] = trow[jj];
                                    else
                                        for (int jj = 0; jj < nr; jj++) crow[jj] += trow[jj];
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
